(4304820, 620283, 46778, '<td valign="top">Even though I think that you have a technically good shoot, I would not buy this car :) IMHO 6</td>', 'Even though I think that you have a technically good shoot, I would not buy this car :) IMHO 6', '2007-12-10 00:15:17.000000', NULL, 1),
(4304825, 620348, 31637, '<td valign="top">What a gem. One of my top ten favorite cars ever. Sephia was a great choice.</td>', 'What a gem. One of my top ten favorite cars ever. Sephia was a great choice.', '2007-12-10 00:17:39.000000', NULL, 1),
(4304827, 621125, 31637, '<td valign="top">Very nicely done, tough shot.</td>', 'Very nicely done, tough shot.', '2007-12-10 00:19:17.000000', NULL, 1),
(4304830, 621092, 46778, '<td valign="top">Very nice composition and B&amp;W conversion - The car is a clear focus of the picture and it is a believable ad. The light''s adds a touch of class. Given the fact that I think that it is a good B&amp;W, I wonder if it would look better in color?  IMHO 7</td>', 'Very nice composition and B&W conversion - The car is a clear focus of the picture and it is a believable ad. The light''s adds a touch of class. Given the fact that I think that it is a good B&W, I wonder if it would look better in color?  IMHO 7', '2007-12-10 00:19:41.000000', NULL, 1),
(4304831, 621077, 31637, '<td valign="top">Awesome shot, the background is cool, and good choice to desaturate.</td>', 'Awesome shot, the background is cool, and good choice to desaturate.', '2007-12-10 00:20:04.000000', NULL, 1),
(4304833, 621051, 31637, '<td valign="top">Great timely capture and sense of speed.</td>', 'Great timely capture and sense of speed.', '2007-12-10 00:20:35.000000', NULL, 1),
