(4305017, 621081, 46778, '<td valign="top">Very good shoot for a car ad, especial in an urban area. I wish the white strip on the left of the car was not there or nice and fresh. IMHO -7-</td>', 'Very good shoot for a car ad, especial in an urban area. I wish the white strip on the left of the car was not there or nice and fresh. IMHO -7-', '2007-12-10 01:12:28.000000', NULL, 1),
(4305022, 620881, 46778, '<td valign="top">Very dramatic post processing for a beautiful car. With the great leading line of the road I almost would have like to see the car a little more to the left of the picture. You should do very well in this competition. -8-</td>', 'Very dramatic post processing for a beautiful car. With the great leading line of the road I almost would have like to see the car a little more to the left of the picture. You should do very well in this competition. -8-', '2007-12-10 01:15:27.000000', NULL, 1),
(4305026, 620283, 78821, '<td valign="top">Your picture literally made me tilt my head sideways to get a better look. Don''t know if that''s good or not, but it did grab my attention. I like the colors, vignetting, and the stab at humor here, but not sure about the composition.</td>', 'Your picture literally made me tilt my head sideways to get a better look. Don''t know if that''s good or not, but it did grab my attention. I like the colors, vignetting, and the stab at humor here, but not sure about the composition.', '2007-12-10 01:16:26.000000', NULL, 1),
