(4305037, 621027, 46778, '<td valign="top">Good technical shoot. Not selling me on a particular car, but more on a brand. -5-</td>', 'Good technical shoot. Not selling me on a particular car, but more on a brand. -5-', '2007-12-10 01:22:21.000000', NULL, 1),
