(4305792, 620917, 63398, '<td valign="top">A really ordinary vehicle and dealer name with an extremely well executed ad for same. Great job doing so. 8</td>', 'A really ordinary vehicle and dealer name with an extremely well executed ad for same. Great job doing so. 8', '2007-12-10 09:02:23.000000', NULL, 1),
