(4306366, 621087, 68586, '<td valign="top">Perfect backdrop for the car.</td>', 'Perfect backdrop for the car.', '2007-12-10 13:29:28.000000', NULL, 1),
(4306371, 620946, 68586, '<td valign="top">truly wonderful road, I''m not quite sure the car fits the title though - something a little less mainstream would have had much more visual impact for me.<br/> <br/>Great idea though</td>', 'truly wonderful road, I''m not quite sure the car fits the title though - something a little less mainstream would have had much more visual impact for me. Great idea though', '2007-12-10 13:32:14.000000', NULL, 1),
(4306373, 621047, 68586, '<td valign="top">I hate to be picky . .but it''s bonnet badge says it''s a Bentley - not a Rolls . . <br/> <br/>Still a wonderfull Christmas present though.<br/> <br/>If you could get rid of the reflections this would be a really strong shot.</td>', 'I hate to be picky . .but it''s bonnet badge says it''s a Bentley - not a Rolls . .  Still a wonderfull Christmas present though. If you could get rid of the reflections this would be a really strong shot.', '2007-12-10 13:34:24.000000', NULL, 1),
