(4311598, 620744, 67152, '<td valign="top">A cool and out of the box entry.  I like it. 7</td>', 'A cool and out of the box entry.  I like it. 7', '2007-12-12 17:25:14.000000', NULL, 1),
(4311602, 620945, 67152, '<td valign="top">Wonderful location.  I am not sold on the lighting on the car.  I would have liked a bit more shine.</td>', 'Wonderful location.  I am not sold on the lighting on the car.  I would have liked a bit more shine.', '2007-12-12 17:25:59.000000', NULL, 1),
(4311605, 620539, 67152, '<td valign="top">What a great grill this car has.  It sure would be fun to get this thing going and work on.  The close crop works really well here, I just wish it were a bit sharper in focus.</td>', 'What a great grill this car has.  It sure would be fun to get this thing going and work on.  The close crop works really well here, I just wish it were a bit sharper in focus.', '2007-12-12 17:27:53.000000', NULL, 1),
