(4311609, 620618, 67152, '<td valign="top">Really good work.  Nice perspective and great message told by this image.</td>', 'Really good work.  Nice perspective and great message told by this image.', '2007-12-12 17:29:39.000000', NULL, 1),
(4311616, 621047, 67152, '<td valign="top">Pretty car.  The image really suffers from the reflection created by the glass.  In addition, the crop seems forced - i want to see the whole grill - and also the background is distracting</td>', 'Pretty car.  The image really suffers from the reflection created by the glass.  In addition, the crop seems forced - i want to see the whole grill - and also the background is distracting', '2007-12-12 17:32:45.000000', NULL, 1),
