(4311820, 620123, 67152, '<td valign="top">Good perspective and nice background.  I like the angle of the shot on the truck so that we can see the hood and cab and bed.</td>', 'Good perspective and nice background.  I like the angle of the shot on the truck so that we can see the hood and cab and bed.', '2007-12-12 19:57:59.000000', NULL, 1),
(4311822, 621010, 67152, '<td valign="top">Very beautiful and spooky image - I can see this as part of a more complete ad campaign or series of pictures to tell the story of this vehicle.  It works for me!!!</td>', 'Very beautiful and spooky image - I can see this as part of a more complete ad campaign or series of pictures to tell the story of this vehicle.  It works for me!!!', '2007-12-12 19:59:10.000000', NULL, 1),
(4311823, 621106, 67152, '<td valign="top">I love the perspective and the elongated lines that the wide ange generates - i would just lose the model/ man in the driver seat - he distracts from the lines of the car.</td>', 'I love the perspective and the elongated lines that the wide ange generates - i would just lose the model/ man in the driver seat - he distracts from the lines of the car.', '2007-12-12 20:00:10.000000', NULL, 1),
