(4312052, 620837, 60495, '<td valign="top">The reflection on the window is a real distraction which will hurt the score but the composition is nice.</td>', 'The reflection on the window is a real distraction which will hurt the score but the composition is nice.', '2007-12-12 22:54:11.000000', NULL, 1),
(4312054, 621106, 60495, '<td valign="top">I like the perspective on this one, not sure if the front bumper could have been shined up a bit but that would help the shot. Overall very nice. 7</td>', 'I like the perspective on this one, not sure if the front bumper could have been shined up a bit but that would help the shot. Overall very nice. 7', '2007-12-12 22:58:54.000000', NULL, 1),
