(4312287, 620282, 68504, '<td valign="top">Good DOF, colour, but the upper part of the photo is just a tad boring for the promise of the car.</td>', 'Good DOF, colour, but the upper part of the photo is just a tad boring for the promise of the car.', '2007-12-13 02:42:04.000000', NULL, 1),
(4312289, 621067, 68504, '<td valign="top">Nice angle, and the sky works well with the silver but the vegetation detracts  from the smooth lines.</td>', 'Nice angle, and the sky works well with the silver but the vegetation detracts  from the smooth lines.', '2007-12-13 02:45:34.000000', NULL, 1),
(4312293, 621074, 68504, '<td valign="top">Wonderful background and splash.</td>', 'Wonderful background and splash.', '2007-12-13 02:49:04.000000', NULL, 1),
(4312294, 620921, 68504, '<td valign="top">Oh my.  Doesn''t loosen my inadequate purse strings, but I sure like the picture.</td>', 'Oh my.  Doesn''t loosen my inadequate purse strings, but I sure like the picture.', '2007-12-13 02:51:40.000000', NULL, 1),
(4312295, 621128, 68504, '<td valign="top">I''d like to see more of this - not the car, but playing with the composition and reflections.  Nice take.</td>', 'I''d like to see more of this - not the car, but playing with the composition and reflections.  Nice take.', '2007-12-13 02:56:14.000000', NULL, 1),
(4312336, 620002, 73866, '<td valign="top">very cute... love the perspective.</td>', 'very cute... love the perspective.', '2007-12-13 04:40:10.000000', NULL, 1),
(4312356, 621051, 86540, '<td valign="top">hopefully this is the winner, you deserver it.  wow.</td>', 'hopefully this is the winner, you deserver it.  wow.', '2007-12-13 06:21:09.000000', NULL, 1),
(4312390, 620754, 30982, '<td valign="top">I like that this was shot while moving, or so it appears!</td>', 'I like that this was shot while moving, or so it appears!', '2007-12-13 07:02:27.000000', NULL, 1),
(4312392, 620677, 30982, '<td valign="top">LOL!  Did you buy the car before you took the shot or after?  :-)</td>', 'LOL!  Did you buy the car before you took the shot or after?  :-)', '2007-12-13 07:04:17.000000', NULL, 1),
(4312393, 620282, 30982, '<td valign="top">I like how the background color compliments the car.</td>', 'I like how the background color compliments the car.', '2007-12-13 07:05:01.000000', NULL, 1),
(4312395, 620744, 30982, '<td valign="top">Great shot and appropriate title/ad slogan.</td>', 'Great shot and appropriate title/ad slogan.', '2007-12-13 07:06:16.000000', NULL, 1),
(4312397, 621092, 30982, '<td valign="top">Nice location for the shot - good leading lines.</td>', 'Nice location for the shot - good leading lines.', '2007-12-13 07:08:21.000000', NULL, 1),
(4312398, 621010, 30982, '<td valign="top">Cool!  I love the red of the vehicle.  Definitely a very spooky atmosphere.</td>', 'Cool!  I love the red of the vehicle.  Definitely a very spooky atmosphere.', '2007-12-13 07:09:06.000000', NULL, 1),
(4312400, 621051, 30982, '<td valign="top">Great lines for the shot.  Not sure how you managed to get the scenery and road markings blurred but the clouds not.  Has a nice sense of motion to it.</td>', 'Great lines for the shot.  Not sure how you managed to get the scenery and road markings blurred but the clouds not.  Has a nice sense of motion to it.', '2007-12-13 07:11:32.000000', NULL, 1),
(4312401, 620520, 30982, '<td valign="top">The sparkly bokeh on the auto symbol is indeed kinda nifty!</td>', 'The sparkly bokeh on the auto symbol is indeed kinda nifty!', '2007-12-13 07:12:14.000000', NULL, 1),
(4312403, 620908, 30982, '<td valign="top">Straight out of a brochure!  Nice.</td>', 'Straight out of a brochure!  Nice.', '2007-12-13 07:14:19.000000', NULL, 1),
(4312406, 620202, 30982, '<td valign="top">Somehow I''m doubting the offer... :-)</td>', 'Somehow I''m doubting the offer... :-)', '2007-12-13 07:24:43.000000', NULL, 1),
(4312407, 621074, 30982, '<td valign="top">I can see this as an ad.</td>', 'I can see this as an ad.', '2007-12-13 07:25:37.000000', NULL, 1),
(4312408, 621008, 30982, '<td valign="top">Beautiful light for this - nice!</td>', 'Beautiful light for this - nice!', '2007-12-13 07:27:11.000000', NULL, 1),
(4312410, 620618, 30982, '<td valign="top">Nice location, nice different angle, sweet light!</td>', 'Nice location, nice different angle, sweet light!', '2007-12-13 07:29:02.000000', NULL, 1),
(4312411, 621091, 30982, '<td valign="top">LOL!  Definitely a great ad for eBay.</td>', 'LOL!  Definitely a great ad for eBay.', '2007-12-13 07:29:37.000000', NULL, 1),
(4312413, 620889, 30982, '<td valign="top">I like the urban setting - the natural environment for this car.</td>', 'I like the urban setting - the natural environment for this car.', '2007-12-13 07:30:16.000000', NULL, 1),
(4312414, 620917, 30982, '<td valign="top">I like the angle - adds a little zip.</td>', 'I like the angle - adds a little zip.', '2007-12-13 07:31:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4312415, 620881, 30982, '<td valign="top">Lovely location, nice post processing.  Very effective as a sales pitch.</td>', 'Lovely location, nice post processing.  Very effective as a sales pitch.', '2007-12-13 07:32:42.000000', NULL, 1),
(4312416, 620921, 63398, '<td valign="top"><b>A Perfect 10</b></td>', 'A Perfect 10', '2007-12-13 07:33:43.000000', NULL, 1),
(4312418, 620921, 30982, '<td valign="top">Nice take on the challenge!  Good air of mystery and intrigue.</td>', 'Nice take on the challenge!  Good air of mystery and intrigue.', '2007-12-13 07:34:57.000000', NULL, 1),
(4312421, 621087, 30982, '<td valign="top">Very good choice of location for the "ad"!  I also like the fact the car is "green".</td>', 'Very good choice of location for the "ad"!  I also like the fact the car is "green".', '2007-12-13 07:37:31.000000', NULL, 1),
(4312422, 620838, 30982, '<td valign="top">Very cool showroom!</td>', 'Very cool showroom!', '2007-12-13 07:38:49.000000', NULL, 1),
(4312423, 621077, 30982, '<td valign="top">Sweet!</td>', 'Sweet!', '2007-12-13 07:39:16.000000', NULL, 1),
(4312511, 621077, 70270, '<td valign="top">My favorite of the challenge.  Not only is it a classic car, the tones and the setting are evocative of the ''50s ... I could definitely see this as a full page ad in LIFE or LOOK magazine.  10</td>', 'My favorite of the challenge.  Not only is it a classic car, the tones and the setting are evocative of the ''50s ... I could definitely see this as a full page ad in LIFE or LOOK magazine.  10', '2007-12-13 09:03:40.000000', NULL, 1),
(4312517, 620881, 70270, '<td valign="top">Beautiful car, great angle, and wonderful sky.  Overprocessed, but that fits with the idea of this as a car ad.  9</td>', 'Beautiful car, great angle, and wonderful sky.  Overprocessed, but that fits with the idea of this as a car ad.  9', '2007-12-13 09:07:33.000000', NULL, 1),
(4312520, 620917, 70270, '<td valign="top">I don''t know exactly why I like this shot but I do ... shot from a car ad like angle, the sky behind is dramatic, and the lighting on the truck really helps it pop from the image.  9</td>', 'I don''t know exactly why I like this shot but I do ... shot from a car ad like angle, the sky behind is dramatic, and the lighting on the truck really helps it pop from the image.  9', '2007-12-13 09:08:29.000000', NULL, 1),
(4312522, 620889, 70270, '<td valign="top">Nice tones and a good low angle.  The car fits well in its environment.  8</td>', 'Nice tones and a good low angle.  The car fits well in its environment.  8', '2007-12-13 09:09:23.000000', NULL, 1),
(4312523, 621008, 70270, '<td valign="top">Great car, and the lighting helps it pop.  The background is kind of flat and doesn''t add much to the image, and the car itself looks a bit oversharpened.  7</td>', 'Great car, and the lighting helps it pop.  The background is kind of flat and doesn''t add much to the image, and the car itself looks a bit oversharpened.  7', '2007-12-13 09:10:56.000000', NULL, 1),
(4312524, 620282, 70270, '<td valign="top">This really looks like a car ad.  Nice angle, good DOF, and leaving the lights on was a nice touch.  8</td>', 'This really looks like a car ad.  Nice angle, good DOF, and leaving the lights on was a nice touch.  8', '2007-12-13 09:11:34.000000', NULL, 1),
(4312525, 620666, 70270, '<td valign="top">Cool car, nice reflection, perfectly sharp, and well exposed ... but the image leaves me a little cold for some reason.  Almost looks plastic, like a toy car.  7</td>', 'Cool car, nice reflection, perfectly sharp, and well exposed ... but the image leaves me a little cold for some reason.  Almost looks plastic, like a toy car.  7', '2007-12-13 09:12:33.000000', NULL, 1),
(4312526, 621106, 70270, '<td valign="top">Cool shot and a great location for an ad shoot.  The horizon is a little off kilter and not sure I like the superwide distortion on the front fender, but definitely looks like an ad.  7</td>', 'Cool shot and a great location for an ad shoot.  The horizon is a little off kilter and not sure I like the superwide distortion on the front fender, but definitely looks like an ad.  7', '2007-12-13 09:14:06.000000', NULL, 1),
(4312528, 620838, 70270, '<td valign="top">This looks like a magazine ad.  The car is well exposed, and the architectural details in the ceiling really help the image.  Onlhy thing that drags this down, but only slightly, is the reflections in the bumper ... looks like I can see you kneeling down to take the shot, while a salesman looks on (or harangues you) off to the left!  8</td>', 'This looks like a magazine ad.  The car is well exposed, and the architectural details in the ceiling really help the image.  Onlhy thing that drags this down, but only slightly, is the reflections in the bumper ... looks like I can see you kneeling down to take the shot, while a salesman looks on (or harangues you) off to the left!  8', '2007-12-13 09:16:27.000000', NULL, 1),
(4312531, 620538, 70270, '<td valign="top">Nice detail of a great old car.  Could be larger, but I''m sure I''m not the first to mention that.  7</td>', 'Nice detail of a great old car.  Could be larger, but I''m sure I''m not the first to mention that.  7', '2007-12-13 09:17:05.000000', NULL, 1),
(4312532, 620831, 70270, '<td valign="top">Nice angle, nice location, nice ad.  7</td>', 'Nice angle, nice location, nice ad.  7', '2007-12-13 09:17:47.000000', NULL, 1),
(4312537, 620520, 70270, '<td valign="top">Nice detail shot that I could see being inset into a larger ad.  I think Audi probably would want a much wider DOF, though, so its logo is as sharp as that S5 badge.  7</td>', 'Nice detail shot that I could see being inset into a larger ad.  I think Audi probably would want a much wider DOF, though, so its logo is as sharp as that S5 badge.  7', '2007-12-13 09:21:51.000000', NULL, 1),
(4312538, 621051, 70270, '<td valign="top">Nice moving pic, and a great sharpness on the car.  Really makes you want to get out and drive.  I think the background would have been better with even more motion blur ... its only slight in the foreground and none further back down the road diminishes the sense of speed you are going for.  7</td>', 'Nice moving pic, and a great sharpness on the car.  Really makes you want to get out and drive.  I think the background would have been better with even more motion blur ... its only slight in the foreground and none further back down the road diminishes the sense of speed you are going for.  7', '2007-12-13 09:23:10.000000', NULL, 1),
(4312541, 621125, 70270, '<td valign="top">Nice shot, and a good twist doing it at night, but I don''t really see this selling the truck.  Still a 6 from me.</td>', 'Nice shot, and a good twist doing it at night, but I don''t really see this selling the truck.  Still a 6 from me.', '2007-12-13 09:24:05.000000', NULL, 1),
(4312542, 620908, 70270, '<td valign="top">Great idea and nice job showing both the interior and exterior of the mustang, but something seems fake to me in the overly white background (not in a rules violation way, just in a reality way), so that brings this down a bit. 6</td>', 'Great idea and nice job showing both the interior and exterior of the mustang, but something seems fake to me in the overly white background (not in a rules violation way, just in a reality way), so that brings this down a bit. 6', '2007-12-13 09:25:37.000000', NULL, 1),
(4312544, 620925, 70270, '<td valign="top">Nice detail shot that could be part of a larger car ad, and a nice reflection on the Jag.  A little grainy and soft, but nicely composed.  6</td>', 'Nice detail shot that could be part of a larger car ad, and a nice reflection on the Jag.  A little grainy and soft, but nicely composed.  6', '2007-12-13 09:26:29.000000', NULL, 1),
(4312548, 621069, 70270, '<td valign="top">Great sky and background, a nice sharp image.  Problem for me is the car is too  chopped up by the composition, so the focal interest is on the sky and asphalt, and not so much on the car.  6</td>', 'Great sky and background, a nice sharp image.  Problem for me is the car is too  chopped up by the composition, so the focal interest is on the sky and asphalt, and not so much on the car.  6', '2007-12-13 09:27:30.000000', NULL, 1),
(4312550, 620931, 70270, '<td valign="top">Nice shot of your beemer, well exposed, and great background sky.  The parking lot, fence, tree, and town below are not that interesting, though, and detract from the shot imo.  6</td>', 'Nice shot of your beemer, well exposed, and great background sky.  The parking lot, fence, tree, and town below are not that interesting, though, and detract from the shot imo.  6', '2007-12-13 09:28:48.000000', NULL, 1),
(4312551, 620618, 70270, '<td valign="top">Nice set up and a great location and angle.  Too much shadow on the trunk and I would have showed either more or less of the car ... chopping it down the middle takes away from this image for me.  6</td>', 'Nice set up and a great location and angle.  Too much shadow on the trunk and I would have showed either more or less of the car ... chopping it down the middle takes away from this image for me.  6', '2007-12-13 09:29:49.000000', NULL, 1),
(4312552, 621081, 70270, '<td valign="top">Nice location and angle for your shot.  The buildings are cool, but compete with the car for my attention.  A square crop taking some off the top might have worked better on this one for me.  6</td>', 'Nice location and angle for your shot.  The buildings are cool, but compete with the car for my attention.  A square crop taking some off the top might have worked better on this one for me.  6', '2007-12-13 09:30:35.000000', NULL, 1),
(4312554, 620041, 70270, '<td valign="top">Nice shot, and great use of B+W.  The Caddy may be sleeping, but it looks poised to tackle the weather.  7</td>', 'Nice shot, and great use of B+W.  The Caddy may be sleeping, but it looks poised to tackle the weather.  7', '2007-12-13 09:31:32.000000', NULL, 1),
(4312556, 620539, 70270, '<td valign="top">Nice detail shot, very Wabi Sabi.  For an ad, I''d like to see more of the car.  As a photo, I like this one a lot.  6</td>', 'Nice detail shot, very Wabi Sabi.  For an ad, I''d like to see more of the car.  As a photo, I like this one a lot.  6', '2007-12-13 09:32:29.000000', NULL, 1),
(4312557, 621002, 70270, '<td valign="top">Nice pic, but the shadows on the hood and the sharp background take away from it and make it look more snapshottish to me.  5</td>', 'Nice pic, but the shadows on the hood and the sharp background take away from it and make it look more snapshottish to me.  5', '2007-12-13 09:33:08.000000', NULL, 1),
(4312559, 621067, 70270, '<td valign="top">Nice shot, good angle, and nice tones.  Love the colors in the sky, but not much interest there, so maybe a slightly higher angle to put more of the car in the frame and less negative space would have worked better. 6</td>', 'Nice shot, good angle, and nice tones.  Love the colors in the sky, but not much interest there, so maybe a slightly higher angle to put more of the car in the frame and less negative space would have worked better. 6', '2007-12-13 09:34:17.000000', NULL, 1),
(4312560, 621087, 70270, '<td valign="top">Great idea.  The refinery looks a little off though ... kind of in between being a blurred background and being sharp. Would have liked this better if you had gone one way or the other, and also if the main part of the smoke plume from the stack in the middle was all in the shot.  5</td>', 'Great idea.  The refinery looks a little off though ... kind of in between being a blurred background and being sharp. Would have liked this better if you had gone one way or the other, and also if the main part of the smoke plume from the stack in the middle was all in the shot.  5', '2007-12-13 09:35:36.000000', NULL, 1),
(4312561, 620861, 70270, '<td valign="top">Interesting shot and cool use of blur, though it kind of disappears at the top and loses its form.  6</td>', 'Interesting shot and cool use of blur, though it kind of disappears at the top and loses its form.  6', '2007-12-13 09:36:13.000000', NULL, 1),
(4312562, 621010, 70270, '<td valign="top">I really like this shot.  Probably at least a 7 from me, maybe an 8 or 9 in another challenge.  As a car ad, though, I don''t see it.  5</td>', 'I really like this shot.  Probably at least a 7 from me, maybe an 8 or 9 in another challenge.  As a car ad, though, I don''t see it.  5', '2007-12-13 09:37:02.000000', NULL, 1),
(4312564, 620568, 70270, '<td valign="top">Funky processing is gonna knock you down, but dial it back just a little bit and I can see this as an ad in an edgy youth-oriented publication.  5 as it is, though.</td>', 'Funky processing is gonna knock you down, but dial it back just a little bit and I can see this as an ad in an edgy youth-oriented publication.  5 as it is, though.', '2007-12-13 09:38:13.000000', NULL, 1),
(4312565, 620123, 70270, '<td valign="top">Nice pic, but looks kind of like a snapshot to me.  I can see it selling the truck in the Auto Trader, but as a photo its just a 5.</td>', 'Nice pic, but looks kind of like a snapshot to me.  I can see it selling the truck in the Auto Trader, but as a photo its just a 5.', '2007-12-13 09:38:51.000000', NULL, 1),
(4312568, 620002, 70270, '<td valign="top">I don''t really know what to do with this one.  Its a great pic, well lit, sharp, and a bit of fun thrown in for good measure, like most of your work.  But its a bit of a stretch for me, and the focus is on your kid, not the toy truck (and it doesn''t look like he''s gonna let go of it and let you sell it anytime soon, either!).  In another challenge, its a 7+.  Here its a 5.</td>', 'I don''t really know what to do with this one.  Its a great pic, well lit, sharp, and a bit of fun thrown in for good measure, like most of your work.  But its a bit of a stretch for me, and the focus is on your kid, not the toy truck (and it doesn''t look like he''s gonna let go of it and let you sell it anytime soon, either!).  In another challenge, its a 7+.  Here its a 5.', '2007-12-13 09:40:54.000000', NULL, 1),
(4312632, 621047, 63398, '<td valign="top">Great concept....I actually discarded one of my offerings due to the reflection in the showroom glass. I believe that there''s a way to remove that, but I don''t know how. BTW, that''s a Bentley.</td>', 'Great concept....I actually discarded one of my offerings due to the reflection in the showroom glass. I believe that there''s a way to remove that, but I don''t know how. BTW, that''s a Bentley.', '2007-12-13 10:32:22.000000', NULL, 1),
(4312749, 620520, 13879, '<td valign="top">nice bokeh (beast of a car as well!) 9</td>', 'nice bokeh (beast of a car as well!) 9', '2007-12-13 11:24:21.000000', NULL, 1),
(4312763, 620979, 66597, '<td valign="top">Oh, man, I''ve got one of these, maybe I''m compensating... LOL.</td>', 'Oh, man, I''ve got one of these, maybe I''m compensating... LOL.', '2007-12-13 11:31:26.000000', NULL, 1),
(4312766, 620568, 66597, '<td valign="top">The car looks good, but the processing behind is really weird looking, sorry.</td>', 'The car looks good, but the processing behind is really weird looking, sorry.', '2007-12-13 11:32:17.000000', NULL, 1),
(4312776, 620881, 66597, '<td valign="top">Awesome, my pick for the blue</td>', 'Awesome, my pick for the blue', '2007-12-13 11:36:32.000000', NULL, 1),
(4312990, 620917, 87698, '<td valign="top">excellent photo!</td>', 'excellent photo!', '2007-12-13 14:07:00.000000', NULL, 1),
(4313010, 621047, 86779, '<td valign="top">That''s a Bentley?</td>', 'That''s a Bentley?', '2007-12-13 14:21:09.000000', NULL, 1),
(4313012, 620677, 86779, '<td valign="top">Imaginative!</td>', 'Imaginative!', '2007-12-13 14:21:25.000000', NULL, 1),
(4313013, 621091, 86779, '<td valign="top">Like it!</td>', 'Like it!', '2007-12-13 14:21:38.000000', NULL, 1),
