(4313019, 621106, 86779, '<td valign="top">Great photo!</td>', 'Great photo!', '2007-12-13 14:22:21.000000', NULL, 1),
(4313024, 621009, 86779, '<td valign="top">Good photo, but not as good as the Viper.</td>', 'Good photo, but not as good as the Viper.', '2007-12-13 14:23:12.000000', NULL, 1),
(4313099, 620754, 77192, '<td valign="top">in your face it certainly is, but no bad thing. I like it :-)</td>', 'in your face it certainly is, but no bad thing. I like it :-)', '2007-12-13 15:22:08.000000', NULL, 1),
(4313100, 621002, 77192, '<td valign="top">I don''t know if it''s just the angle, but I''m not very excited by it. Sorry.</td>', 'I don''t know if it''s just the angle, but I''m not very excited by it. Sorry.', '2007-12-13 15:22:42.000000', NULL, 1),
(4313101, 621067, 77192, '<td valign="top">very nice, slightly moody</td>', 'very nice, slightly moody', '2007-12-13 15:23:03.000000', NULL, 1),
(4313104, 621077, 77192, '<td valign="top">I love the vintage pp you did...how did you do it? Oh, and a lovely car too.</td>', 'I love the vintage pp you did...how did you do it? Oh, and a lovely car too.', '2007-12-13 15:23:40.000000', NULL, 1),
