(4313332, 620946, 68504, '<td valign="top">Like the perspective and colour.  Regret car seems a little blurry.</td>', 'Like the perspective and colour.  Regret car seems a little blurry.', '2007-12-13 17:37:05.000000', NULL, 1),
(4313336, 620666, 77838, '<td valign="top">Sweet detail in the car; I love the faint reflection in the surface of the table.</td>', 'Sweet detail in the car; I love the faint reflection in the surface of the table.', '2007-12-13 17:40:20.000000', NULL, 1),
(4313338, 621087, 68504, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2007-12-13 17:41:18.000000', NULL, 1),
