(4314746, 620538, 72131, '<td valign="top">Niceee, but to small :/</td>', 'Niceee, but to small :/', '2007-12-14 13:50:52.000000', NULL, 1),
(4314751, 620831, 72131, '<td valign="top">Blue Ribbonnnnn</td>', 'Blue Ribbonnnnn', '2007-12-14 13:53:06.000000', NULL, 1),
(4315047, 620618, 3746, '<td valign="top">Good shot, nice to see a 4x4 in its real environment. The car looking towards the distance gives its some personality. very good, should do well.<br/> <br/>bumped from an 8 to a 9.. well done.</td>', 'Good shot, nice to see a 4x4 in its real environment. The car looking towards the distance gives its some personality. very good, should do well. bumped from an 8 to a 9.. well done.', '2007-12-14 17:34:40.000000', NULL, 1),
