(4317146, 620831, 65234, '<td valign="top">Great angle; complementary background.  Pretty much perfect.</td>', 'Great angle; complementary background.  Pretty much perfect.', '2007-12-16 13:23:16.000000', NULL, 1),
(4317148, 621125, 65234, '<td valign="top">Nice effect!  Peace and quiet while the world goes zipping by.</td>', 'Nice effect!  Peace and quiet while the world goes zipping by.', '2007-12-16 13:24:31.000000', NULL, 1),
(4317149, 620666, 65234, '<td valign="top">On those flat tires?  Nice reflection but it''s still a toy.</td>', 'On those flat tires?  Nice reflection but it''s still a toy.', '2007-12-16 13:26:44.000000', NULL, 1),
(4317151, 621091, 65234, '<td valign="top">Not terribly appealing.</td>', 'Not terribly appealing.', '2007-12-16 13:27:59.000000', NULL, 1),
(4317156, 621106, 65234, '<td valign="top">First ad I''ve seen with a real model.  Nice perspective and great background.  Love the deep blue of the sky (I do see a bit of odd color banding in it, though; could just be an effect of resizing).</td>', 'First ad I''ve seen with a real model.  Nice perspective and great background.  Love the deep blue of the sky (I do see a bit of odd color banding in it, though; could just be an effect of resizing).', '2007-12-16 13:31:34.000000', NULL, 1),
(4317165, 621081, 65234, '<td valign="top">The composition is nice, but the car looks kind of bland in comparison to the red building and bright blue sky.</td>', 'The composition is nice, but the car looks kind of bland in comparison to the red building and bright blue sky.', '2007-12-16 13:37:05.000000', NULL, 1),
(4317227, 620618, 85510, '<td valign="top">Despite the insane drop-off, this feels very cozy. I also love it as an ad idea. Great job!</td>', 'Despite the insane drop-off, this feels very cozy. I also love it as an ad idea. Great job!', '2007-12-16 15:09:31.000000', NULL, 1),
