(4317566, 621106, 48227, '<td valign="top">Excellent shot. 10</td>', 'Excellent shot. 10', '2007-12-16 21:50:19.000000', NULL, 1),
(4317657, 620831, 53094, '<td valign="top">I really like the wide angle perspective of this shot, and the background is absolutely perfect for a car ad.  Perfect for this challenge.</td>', 'I really like the wide angle perspective of this shot, and the background is absolutely perfect for a car ad.  Perfect for this challenge.', '2007-12-16 23:23:55.000000', NULL, 1),
(4317660, 621087, 53094, '<td valign="top">Great concept, and well executed!  If I would change anything, it would be to have just a little more foreground.</td>', 'Great concept, and well executed!  If I would change anything, it would be to have just a little more foreground.', '2007-12-16 23:25:42.000000', NULL, 1),
(4317668, 621106, 61961, '<td valign="top">Looks like this may be my only "10" in this challenge.  Great shot, very well lit.  Love the shooting angle, the dramatic backdrop and the use of a model.  Beautiful car!</td>', 'Looks like this may be my only "10" in this challenge.  Great shot, very well lit.  Love the shooting angle, the dramatic backdrop and the use of a model.  Beautiful car!', '2007-12-16 23:30:02.000000', NULL, 1),
(4317670, 621077, 61961, '<td valign="top">Nice processing on this, and absolutely fantastic car (T-birds were always my favorite).</td>', 'Nice processing on this, and absolutely fantastic car (T-birds were always my favorite).', '2007-12-16 23:31:34.000000', NULL, 1),
(4317672, 621051, 53094, '<td valign="top">This shot is great!  I can''t find anything that I don''t like about it.  A lonely stretch of road, beautiful blue sky with clouds, and the real feel of speed from the blurred motion.  So far, my favorite of the challenge.</td>', 'This shot is great!  I can''t find anything that I don''t like about it.  A lonely stretch of road, beautiful blue sky with clouds, and the real feel of speed from the blurred motion.  So far, my favorite of the challenge.', '2007-12-16 23:33:03.000000', NULL, 1),
(4317675, 621087, 61961, '<td valign="top">A high score from me, and an original take on the challenge.</td>', 'A high score from me, and an original take on the challenge.', '2007-12-16 23:36:04.000000', NULL, 1),
(4317681, 620908, 53094, '<td valign="top">Great...looks like a real ad.</td>', 'Great...looks like a real ad.', '2007-12-16 23:45:53.000000', NULL, 1),
(4317685, 620838, 15711, '<td valign="top">Having been in the business and being married to someone who''s been in it over 25 years, I''ve seen all kinds of brochures and literature.  I think this is a fine example. I might like a bit more neg space just to the left of the vehicle, but that''s nitpicking. 8</td>', 'Having been in the business and being married to someone who''s been in it over 25 years, I''ve seen all kinds of brochures and literature.  I think this is a fine example. I might like a bit more neg space just to the left of the vehicle, but that''s nitpicking. 8', '2007-12-16 23:49:09.000000', NULL, 1),
(4317686, 621051, 15711, '<td valign="top">Love the motion blur.  This does look like something in a brochure.</td>', 'Love the motion blur.  This does look like something in a brochure.', '2007-12-16 23:49:28.000000', NULL, 1),
(4317687, 620618, 15711, '<td valign="top">I can seriously see this as a smaller shot on a big glossy page of a brochure. I might have included the back end of the vehicle, instead of it being in shadow.</td>', 'I can seriously see this as a smaller shot on a big glossy page of a brochure. I might have included the back end of the vehicle, instead of it being in shadow.', '2007-12-16 23:50:27.000000', NULL, 1),
